static inline int bayes_model_predict(const float *features, int length) {
    int best_class = 0;
    float best_log_prob = -1e30f;

    for (int c = 0; c < BAYES_NUM_CLASSES; c++) {
        float log_prob = bayes_log_priors[c];
        for (int j = 0; j < length; j++) {
            float diff = features[j] - bayes_means[c][j];
            float v = bayes_variances[c][j];
            // Gaussian log-likelihood: -0.5 * (log(2*pi*v) + (x - mu)^2 / v)
            log_prob -= 0.5f * (logf(6.2831853f * v) + (diff * diff) / v);
        }
        if (log_prob > best_log_prob) {
            best_log_prob = log_prob;
            best_class = c;
        }
    }
    return best_class;
}

